  shop: 12, store: 12, online: 14, site: 14, website: 14, space: 16,
  fit: 16, monster: 20, bar: 16, autos: 18, boats: 16, christmas: 16,
  lol: 16, mom: 16, pics: 16, wiki: 12, su: 20, cc: 12, pw: 20, am: 12,
